def solve(html):
    text = html
    low = text.lower()
    start = low.find("<script")
    while start != -1:
        end = low.find("</script>", start)
        if end == -1:
            end = len(text)
        else:
            end += len("</script>")
        text = text[:start] + text[end:]
        low = text.lower()
        start = low.find("<script")
    return text.strip()

def main():
    import sys
    data = sys.stdin.read().strip()
    if not data:
        return
    print(solve(data))

if __name__ == "__main__":
    main()

